double *cutSquares(int *square1, int *square2, int *returnSize) {
  double c1x = square1[0] + square1[2] / 2.0, c1y = square1[1] + square1[2] / 2.0;
  double c2x = square2[0] + square2[2] / 2.0, c2y = square2[1] + square2[2] / 2.0;
  double *res = (double *)malloc(sizeof(double) * 4);
  *returnSize = 4;
  if (fabs(c1x - c2x) < 1e-12) {
    res[0] = c1x;
    res[1] = fmin(square1[1], square2[1]);
    res[2] = c1x;
    res[3] = fmax(square1[1] + square1[2], square2[1] + square2[2]);
    return res;
  }
  double k = (c2y - c1y) / (c2x - c1x);
  double b = c1y - k * c1x;
  double pts[16][2];
  int n = 0;
  double sq[2][3] = {{square1[0], square1[1], square1[2]}, {square2[0], square2[1], square2[2]}};
  for (int s = 0; s < 2; s++) {
    double x0 = sq[s][0], y0 = sq[s][1], side = sq[s][2];
    double xs[2] = {x0, x0 + side};
    for (int t = 0; t < 2; t++) {
      double x = xs[t], y = k * x + b;
      if (y >= y0 - 1e-6 && y <= y0 + side + 1e-6) {
        pts[n][0] = x;
        pts[n][1] = y;
        n++;
      }
    }
    if (fabs(k) > 1e-12) {
      double ys[2] = {y0, y0 + side};
      for (int t = 0; t < 2; t++) {
        double y = ys[t], x = (y - b) / k;
        if (x >= x0 - 1e-6 && x <= x0 + side + 1e-6) {
          pts[n][0] = x;
          pts[n][1] = y;
          n++;
        }
      }
    }
  }
  int mini = 0, maxi = 0;
  for (int i = 1; i < n; i++) {
    if (pts[i][0] < pts[mini][0] || (pts[i][0] == pts[mini][0] && pts[i][1] < pts[mini][1])) mini = i;
    if (pts[i][0] > pts[maxi][0] || (pts[i][0] == pts[maxi][0] && pts[i][1] > pts[maxi][1])) maxi = i;
  }
  res[0] = pts[mini][0];
  res[1] = pts[mini][1];
  res[2] = pts[maxi][0];
  res[3] = pts[maxi][1];
  return res;
}

class Solution {
public:
  vector<double> cutSquares(vector<int> &square1, vector<int> &square2) {
    double c1x = square1[0] + square1[2] / 2.0, c1y = square1[1] + square1[2] / 2.0;
    double c2x = square2[0] + square2[2] / 2.0, c2y = square2[1] + square2[2] / 2.0;
    if (fabs(c1x - c2x) < 1e-12) {
      return {c1x, min((double)square1[1], (double)square2[1]), c1x,
              max((double)square1[1] + square1[2], (double)square2[1] + square2[2])};
    }
    double k = (c2y - c1y) / (c2x - c1x);
    double b = c1y - k * c1x;
    vector<pair<double, double>> pts;
    vector<vector<int>> squares = {square1, square2};
    for (auto &sq : squares) {
      double x0 = sq[0], y0 = sq[1], side = sq[2];
      for (double x : {x0, x0 + side}) {
        double y = k * x + b;
        if (y >= y0 - 1e-6 && y <= y0 + side + 1e-6) pts.push_back({x, y});
      }
      if (fabs(k) > 1e-12) {
        for (double y : {y0, y0 + side}) {
          double x = (y - b) / k;
          if (x >= x0 - 1e-6 && x <= x0 + side + 1e-6) pts.push_back({x, y});
        }
      }
    }
    sort(pts.begin(), pts.end());
    return {pts.front().first, pts.front().second, pts.back().first, pts.back().second};
  }
};

func cutSquares(square1 []int, square2 []int) []float64 {
	c1x, c1y := float64(square1[0])+float64(square1[2])/2, float64(square1[1])+float64(square1[2])/2
	c2x, c2y := float64(square2[0])+float64(square2[2])/2, float64(square2[1])+float64(square2[2])/2
	if math.Abs(c1x-c2x) < 1e-12 {
		bottom := math.Min(float64(square1[1]), float64(square2[1]))
		top := math.Max(float64(square1[1]+square1[2]), float64(square2[1]+square2[2]))
		return []float64{c1x, bottom, c1x, top}
	}
	k := (c2y - c1y) / (c2x - c1x)
	b := c1y - k*c1x
	var pts [][2]float64
	for _, sq := range [][]int{square1, square2} {
		x0, y0, side := float64(sq[0]), float64(sq[1]), float64(sq[2])
		for _, x := range []float64{x0, x0 + side} {
			y := k*x + b
			if y >= y0-1e-6 && y <= y0+side+1e-6 {
				pts = append(pts, [2]float64{x, y})
			}
		}
		if math.Abs(k) > 1e-12 {
			for _, y := range []float64{y0, y0 + side} {
				x := (y - b) / k
				if x >= x0-1e-6 && x <= x0+side+1e-6 {
					pts = append(pts, [2]float64{x, y})
				}
			}
		}
	}
	sort.Slice(pts, func(i, j int) bool {
		if pts[i][0] != pts[j][0] {
			return pts[i][0] < pts[j][0]
		}
		return pts[i][1] < pts[j][1]
	})
	return []float64{pts[0][0], pts[0][1], pts[len(pts)-1][0], pts[len(pts)-1][1]}
}

class Solution {
  public double[] cutSquares(int[] square1, int[] square2) {
    double c1x = square1[0] + square1[2] / 2.0, c1y = square1[1] + square1[2] / 2.0;
    double c2x = square2[0] + square2[2] / 2.0, c2y = square2[1] + square2[2] / 2.0;
    if (Math.abs(c1x - c2x) < 1e-12) {
      double bottom = Math.min(square1[1], square2[1]);
      double top = Math.max(square1[1] + square1[2], square2[1] + square2[2]);
      return new double[] { c1x, bottom, c1x, top };
    }
    double k = (c2y - c1y) / (c2x - c1x);
    double b = c1y - k * c1x;
    List<double[]> pts = new ArrayList<>();
    for (int[] sq : new int[][] { square1, square2 }) {
      double x0 = sq[0], y0 = sq[1], side = sq[2];
      for (double x : new double[] { x0, x0 + side }) {
        double y = k * x + b;
        if (y >= y0 - 1e-6 && y <= y0 + side + 1e-6) pts.add(new double[] { x, y });
      }
      if (Math.abs(k) > 1e-12) {
        for (double y : new double[] { y0, y0 + side }) {
          double x = (y - b) / k;
          if (x >= x0 - 1e-6 && x <= x0 + side + 1e-6) pts.add(new double[] { x, y });
        }
      }
    }
    pts.sort((a, c) -> a[0] != c[0] ? Double.compare(a[0], c[0]) : Double.compare(a[1], c[1]));
    return new double[] { pts.get(0)[0], pts.get(0)[1], pts.get(pts.size() - 1)[0], pts.get(pts.size() - 1)[1] };
  }
}

class Solution:
    def cutSquares(self, square1: List[int], square2: List[int]) -> List[float]:
        c1x, c1y = square1[0] + square1[2] / 2, square1[1] + square1[2] / 2
        c2x, c2y = square2[0] + square2[2] / 2, square2[1] + square2[2] / 2
        if abs(c1x - c2x) < 1e-12:
            bottom = min(square1[1], square2[1])
            top = max(square1[1] + square1[2], square2[1] + square2[2])
            return [c1x, bottom, c1x, top]
        k = (c2y - c1y) / (c2x - c1x)
        b = c1y - k * c1x
        pts = []
        for x0, y0, side in (square1, square2):
            for x in (x0, x0 + side):
                y = k * x + b
                if y0 - 1e-6 <= y <= y0 + side + 1e-6:
                    pts.append((x, y))
            if abs(k) > 1e-12:
                for y in (y0, y0 + side):
                    x = (y - b) / k
                    if x0 - 1e-6 <= x <= x0 + side + 1e-6:
                        pts.append((x, y))
        pts.sort()
        return [pts[0][0], pts[0][1], pts[-1][0], pts[-1][1]]

impl Solution {
  pub fn cut_squares(square1: Vec<i32>, square2: Vec<i32>) -> Vec<f64> {
    let c1x = square1[0] as f64 + square1[2] as f64 / 2.0;
    let c1y = square1[1] as f64 + square1[2] as f64 / 2.0;
    let c2x = square2[0] as f64 + square2[2] as f64 / 2.0;
    let c2y = square2[1] as f64 + square2[2] as f64 / 2.0;
    if (c1x - c2x).abs() < 1e-12 {
      let bottom = (square1[1] as f64).min(square2[1] as f64);
      let top = (square1[1] + square1[2]).max(square2[1] + square2[2]) as f64;
      return vec![c1x, bottom, c1x, top];
    }
    let k = (c2y - c1y) / (c2x - c1x);
    let b = c1y - k * c1x;
    let mut pts: Vec<(f64, f64)> = vec![];
    for sq in [&square1, &square2] {
      let x0 = sq[0] as f64;
      let y0 = sq[1] as f64;
      let side = sq[2] as f64;
      for x in [x0, x0 + side] {
        let y = k * x + b;
        if y >= y0 - 1e-6 && y <= y0 + side + 1e-6 {
          pts.push((x, y));
        }
      }
      if k.abs() > 1e-12 {
        for y in [y0, y0 + side] {
          let x = (y - b) / k;
          if x >= x0 - 1e-6 && x <= x0 + side + 1e-6 {
            pts.push((x, y));
          }
        }
      }
    }
    pts.sort_by(|a, b| a.partial_cmp(b).unwrap());
    vec![pts[0].0, pts[0].1, pts[pts.len() - 1].0, pts[pts.len() - 1].1]
  }
}

const cutSquares = (square1: number[], square2: number[]): number[] => {
  const c1x = square1[0] + square1[2] / 2;
  const c1y = square1[1] + square1[2] / 2;
  const c2x = square2[0] + square2[2] / 2;
  const c2y = square2[1] + square2[2] / 2;
  if (Math.abs(c1x - c2x) < 1e-12) {
    const bottom = Math.min(square1[1], square2[1]);
    const top = Math.max(square1[1] + square1[2], square2[1] + square2[2]);
    return [c1x, bottom, c1x, top];
  }
  const k = (c2y - c1y) / (c2x - c1x);
  const b = c1y - k * c1x;
  const pts: number[][] = [];
  for (const sq of [square1, square2]) {
    const x0 = sq[0];
    const y0 = sq[1];
    const side = sq[2];
    for (const x of [x0, x0 + side]) {
      const y = k * x + b;
      if (y >= y0 - 1e-6 && y <= y0 + side + 1e-6) pts.push([x, y]);
    }
    if (Math.abs(k) > 1e-12) {
      for (const y of [y0, y0 + side]) {
        const x = (y - b) / k;
        if (x >= x0 - 1e-6 && x <= x0 + side + 1e-6) pts.push([x, y]);
      }
    }
  }
  pts.sort((a, c) => a[0] - c[0] || a[1] - c[1]);
  return [pts[0][0], pts[0][1], pts[pts.length - 1][0], pts[pts.length - 1][1]];
};
